// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(address caller1, address caller2) public {
        vm.assume(caller1 != address(0));
        vm.assume(caller2 != address(0));

        bool ok1;
        try c.SetLogFile(address(0)) {
            ok1 = true;
        } catch {
            ok1 = false;
        }
        assertTrue(ok1);

        bool ok2;
        vm.prank(caller1);
        try c.SetLogFile(address(0)) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        bool ok3;
        vm.prank(caller2);
        try c.SetLogFile(address(0)) {
            ok3 = true;
        } catch {
            ok3 = false;
        }

        assertTrue(ok2 || ok3);
    }
}
